import{_ as l,h as t,i as e,c as o,v as r,p as s,x as n,m as V,e as p,S as c}from"./chunks/framework.Dvtg8yj2.js";const C=JSON.parse('{"title":"Vera Rubin NVL72：72 GPU 一块机柜加速器","description":"","frontmatter":{"title":"Vera Rubin NVL72：72 GPU 一块机柜加速器","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vera-rubin-nvl72.md","filePath":"llm/vera-rubin-nvl72.md","lastUpdated":1788454257000}'),u={name:"llm/vera-rubin-nvl72.md"};function d(P,a,h,N,A,m){const i=t("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="vera-rubin-nvl72-72-gpu-一块机柜加速器" tabindex="-1">Vera Rubin NVL72：72 GPU 一块机柜加速器 <a class="header-anchor" href="#vera-rubin-nvl72-72-gpu-一块机柜加速器" aria-label="Permalink to &quot;Vera Rubin NVL72：72 GPU 一块机柜加速器&quot;">​</a></h1><div class="epigraph"><p>整柜 72 张 GPU 经 NVLink 6 全互连之后，软件应当把它当成一块机柜级加速器来切模型，而不是 72 台要互相打招呼的主机。</p><footer>—— NVIDIA 对 Vera Rubin NVL72 的公开表述：the entire rack operates as one rack-scale accelerator</footer></div><p>上一篇把 <a href="/llm/rack-as-accelerator">机柜作为逻辑加速器</a> 写成形态：NVLink 域覆盖整柜时，通信与调度按单域设计。本篇把对照物换成 <strong>Vera Rubin NVL72</strong>。NVIDIA 公开材料写：一柜集成 72 个 Rubin GPU 与 36 个 Vera CPU，由 <a href="/llm/nvlink-6">NVLink 6</a> 连接，并配 ConnectX-9 SuperNIC 与 BlueField-4 DPU；柜外再走 Quantum-X800 InfiniBand 或 Spectrum-X 以太网。Blackwell 一代的 GB200 NVL72 已经把「72 GPU 一域」产品化；Rubin 一代把同一形态接到新的六芯片栈上，见 <a href="/llm/rubin-six-chips">六芯片共设计</a>。本篇讨论这柜在编程模型里是什么，不把厂商营销里的训练 GPU 倍数或每 token 成本写成自己的测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若调度器仍按「每 8 卡一个推理副本」切 NVL72，域内交换买了却闲着，宽专家、宽 TP、长上下文 KV 都跨不出去。若把 72 卡当成无差别设备却让集合通信跨出机柜，又把超节点用成了昂贵的 Scale-Out 节点。Vera Rubin 要回答的问题和 GB200 相同：一次 <code>all_reduce</code> 的通信子是整柜还是柜内某子集？HBM 是 72 份近端显存，还是一个能用 NVLink 做远程访问的域？Vera CPU 与 Rubin GPU 的亲和如何绑？</p><p>CUDA 仍然看见 72 个 device id。没有一种 <code>cudaSetDevice</code> 能把整柜 HBM 收成单一指针空间的魔法。公开产品页给出的机柜级容量是<strong>相加</strong>，不是自动统一寻址。逻辑加速器的意思是：通信与调度按单域设计，模型并行把整柜当一份权重来切。统一内存若存在，以 NVLink-C2C 与编程指南为准，见 <a href="/llm/nvlink-c2c-superchip">超芯</a>，本篇不发明「机柜级 malloc」。</p><h3 id="「一块加速器」覆盖计算托盘与交换托盘" tabindex="-1">「一块加速器」覆盖计算托盘与交换托盘 <a class="header-anchor" href="#「一块加速器」覆盖计算托盘与交换托盘" aria-label="Permalink to &quot;「一块加速器」覆盖计算托盘与交换托盘&quot;">​</a></h3><p>NVIDIA 把 NVL72 写成计算托盘加 NVLink 交换托盘的机柜。计算托盘承载 Vera–Rubin 超芯、液冷、柜外网卡；交换托盘把 72 GPU 收成全互连域。第三代 MGX 公开强调无缆托盘与可热插拔交换，使维护窗口按柜级而不是按 PCIe 卡级来写。算法工程师可以不设计歧管，但不能在容量规划里假装功耗与风冷 8 卡机相同。</p><p><span class="marginnote">NVIDIA 2026 年 GTC 材料把 Vera Rubin 平台后补为七芯片（加入 Groq 3 LPU / LPX）。本篇的机柜对象仍是 NVL72：72 GPU + 36 CPU + NVLink 6 域。LPU 机柜是另一条推理加速形态，不要把 256 LPU 的公开规格抄进 NVL72 的 GPU 计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一个超节点编成一份模型并行组。TP 度可以超过 8，只要整组 rank 都在该 NVLink 域内。EP 可以把专家铺满 72 卡，decode 时 All-to-All 仍走域内交换。KV 池按整柜 HBM 规划长上下文或高并发。进程布局上，计算托盘仍跑 OS，编排系统应暴露「本柜 NVLink 域」为拓扑标签，禁止把跨柜 GPU 塞进同一 TP 组。</p><p>集合通信在域内走 NVLink Switch，并可把一部分归约卸到交换内的 <a href="/llm/nvlink-sharp">SHARP</a>。对软件，这意味着 NCCL 的算法选择应针对「大域、高带宽、短距」。跨柜仍然用 Scale-Out 网卡做 DP 与存储，不要让检查点流量去抢 NVLink。DGX SuperPOD 一类公开蓝图用多柜 NVL72 加 Spectrum-X 组成可扩展单元；那是集群，不是把 72 再乘成一张更大的 NVLink 网。</p>',12)),(e(),s(c,null,{default:n(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20RACK%5B%22Vera%20Rubin%20NVL72%20%3D%20%E4%B8%80%E5%9D%97%E6%9C%BA%E6%9F%9C%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A%20%20%20%20VR%5B%2236%20Vera%20CPU%20%2B%2072%20Rubin%20GPU%22%5D%0A%20%20%20%20SW%5B%22NVLink%206%20%E4%BA%A4%E6%8D%A2%E6%89%98%E7%9B%98%22%5D%0A%20%20%20%20VR%20---%20SW%0A%20%20end%0A%20%20RACK%20--%3E%7C%22%E5%9F%9F%E5%86%85%EF%BC%9ATP%20%2F%20%E5%AE%BD%20EP%20%2F%20%E9%95%BF%20KV%22%7C%20MP%5B%22%E4%B8%80%E4%BB%BD%E5%A4%A7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20RACK%20--%3E%7C%22%E6%9F%9C%E5%A4%96%EF%BC%9AIB%20%2F%20Spectrum-X%22%7C%20CL%5B%22%E9%9B%86%E7%BE%A4%EF%BC%9A%E5%89%AF%E6%9C%AC%20%C2%B7%20%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[V(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="训练、后训练与推理各吃域的哪一段" tabindex="-1">训练、后训练与推理各吃域的哪一段 <a class="header-anchor" href="#训练、后训练与推理各吃域的哪一段" aria-label="Permalink to &quot;训练、后训练与推理各吃域的哪一段&quot;">​</a></h3><p>预训练的宽 TP 与 MoE All-to-All 最吃全互连：专家路由是突发、动态的，层次化 Clos 会引入跳数与拥塞。后训练的 RL rollout 与长思维链把 decode 步数拉长，域内带宽决定能否把大副本留在一柜而不拆成跨机 EP。推理服务适合在域内放<strong>一个</strong>大副本：DeepSeek 级 MoE 的专家铺在 72 卡上，避免跨机 decode 的逐步延迟；多个小模型则应显式切分，避免 72 卡被一个 7B 占满。OpenAI 兼容网关看到的仍是 <code>model</code> 字符串，后面是整柜一份还是柜内多份，属于调度。</p><p>Prefill / decode 分离可以发生在超节点内部，KV 走 NVLink 而不是柜外 RDMA。是否值得拆，取决于负载是否互相拖累，而不是因为机柜看起来像集群。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逻辑加速器成立，靠的是域内任意 GPU 对之间不再经过数据中心叶子。交换托盘承担机柜脊：计算托盘连到交换托盘，而不是托盘两两直连成一张不完整的图。于是「机柜脊」是 NVLink 6，不是 Top-of-Rack 以太网。以太网 / IB 网卡仍在，职责是柜外。编程时若把套接字当域内默认路径，等于绕开这块加速器的脊。</p><p>每张 GPU 的 HBM 仍是近端最快；经 NVLink 读远端 HBM 有代价，但代价按加速器互连计。权重按 TP 分片常驻近端；KV 与激活是否远程，要看实现是否做了显式迁移。把每 GPU 的 <a href="/llm/nvlink-6">NVLink 6 卡间 3.6 TB/s</a> 理解成「任意 kernel 都能以该速率扫完全柜 HBM」是错的——那是互连规格，不是单核访存屋顶线。HBM4 的容量与带宽见 <a href="/llm/rubin-gpu-hbm4">Rubin GPU</a>。</p><p><span class="marginnote">Vera CPU 在公开配置里与 GPU 成对出现在超芯 / 托盘中，承担编排、数据搬运与部分 agent 控制面。逻辑加速器包含 CPU 内存与 GPU HBM 两层，不要只数 72 个 CUDA device。一致性模型以 NVLink-C2C 为准。</span></p><h3 id="故障半径与液冷封装" tabindex="-1">故障半径与液冷封装 <a class="header-anchor" href="#故障半径与液冷封装" aria-label="Permalink to &quot;故障半径与液冷封装&quot;">​</a></h3><p>交换托盘或背板故障影响的是整块逻辑加速器的带宽或连通性，而不是「少一台 8 卡服务器」。NVIDIA 公开写热插拔交换托盘、部分填充机柜仍可运行、以及故障时的动态改路；运维手册仍应按柜级爆炸半径来写：液冷、电源架、固件都是柜级。集群调度应能把该柜从副本集摘掉，而不是在半通的 NVLink 域上继续跑 64 路 TP 并抱怨 NCCL 超时。</p><p>液冷进水温度、功率平滑等设施特性属于机柜产品的一部分，本篇不把某一栏千瓦或摄氏度外推成机房通用定额。规划用当时产品页，并用自己的 NCCL 微基准验证域内集合通信。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>操作系统、容器、NUMA、PCIe 设备树仍然是分托盘的。Kubernetes 若按 Pod 绑 8 卡、不理解柜级域，会把逻辑加速器切碎。需要拓扑管理器把「NVL 域」当可分配资源。不要用 NVL72 当借口取消 Scale-Out：训练数据、多副本高可用、跨地域仍然要机柜间网络。不要填写未出现在 NVIDIA 文档里的铜缆单通道速率。</p><p>「一块 GPU」不能理解成可以忽略 TP 切分——72 卡仍要切，只是切完之后通信还在域内。厂商给出的「相对上一代少用若干 GPU 训练」或「推理吞吐倍数」依赖指定模型与精度，本篇不转述为一般定律。形态结论只依赖：72 GPU 一域、柜内 NVLink、柜外 IB / 以太网。</p><p><span class="marginnote">出处：NVIDIA 技术博客 <em>Inside the NVIDIA Vera Rubin Platform: Six New Chips, One AI Supercomputer</em> 与 Vera Rubin NVL72 产品页中的机柜与域描述。带宽数字以官方表为准，不在这里复制整张规格以免过期。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Vera Rubin NVL72 公开形态是 72 个 Rubin GPU + 36 个 Vera CPU，NVLink 6 收成一块机柜加速器。</li><li>CUDA 设备仍是多 id；「一块」指通信域与调度单位。</li><li>TP / 宽 EP / 长 KV 优先落在该域；DP、存储、多柜副本走 Scale-Out。</li><li>故障与维护按柜级爆炸半径写；交换托盘是机柜脊，不是 ToR 以太网。</li><li>不要把厂商加速比或未公开背板速率写进容量规划。</li><li>出处：NVIDIA Vera Rubin NVL72 公开文档；形态对照见 <a href="/llm/rack-as-accelerator">机柜作为逻辑加速器</a>。</li></ul>',16))])}const L=l(u,[["render",d]]);export{C as __pageData,L as default};
